suppressPackageStartupMessages({library(here);library(dplyr);library(readr);library(tibble)})
source(here("scripts","helpers.R")); source(here("scripts","load_recovery.R"))
d <- read_csv(here("data","garmin_daily.csv"),show_col_types=FALSE)
a <- read_csv(here("data","garmin_activities.csv"),show_col_types=FALSE,col_types=cols(activity_id=col_character(),start=col_datetime(),name=col_character(),type_key=col_character(),.default=col_double()))
z <- read_csv(here("data","garmin_activity_zones.csv"),show_col_types=FALSE,col_types=cols(activity_id=col_character(),.default=col_double()))
am <- merge_rides(a,30,3)|>mutate(group=activity_group(type_key))
rhr_ref <- median(d$resting_hr[d$resting_hr>=45],na.rm=T); p <- athlete_profile(rhr_ref)
as <- session_load(am,p,0.4,z); dl <- daily_load_recovery(d,as)
cat("--- Sleep-NA-Tage: hrv_weekly vorhanden? steps?\n")
print(dl|>filter(is.na(sleep_h))|>select(date,steps,resting_hr,hrv_weekly,hrv_status,ready_score,unrecorded)|>as.data.frame())
cat("\n--- gemessene Rad-Fahrten mit HR: HRR\n")
print(as|>filter(type_key=="cycling",!is.na(avg_hr))|>transmute(start,dur=round(duration_min),avg_hr,hrr=round((avg_hr-p$rhr_ref)/(p$hrmax-p$rhr_ref),2)))
cat("\n--- EWMA mit NA-Ausschluss (statt 0)\n")
ew <- function(x,lam){y<-rep(NA_real_,length(x));prev<-NA;for(i in seq_along(x)){if(!is.na(x[i])){prev<-if(is.na(prev))x[i] else lam*x[i]+(1-lam)*prev};y[i]<-prev};y}
dl$acwr_ewma <- ew(dl$load,2/8)/ew(dl$load,2/29)
ok <- !dl$unrecorded & seq_len(nrow(dl))>28
cat("im Band 0.8-1.3: roll",round(mean(dl$acwr[ok]>=.8&dl$acwr[ok]<=1.3,na.rm=T),2)," ewma",round(mean(dl$acwr_ewma[ok]>=.8&dl$acwr_ewma[ok]<=1.3,na.rm=T),2),"\n")
cat("ACWR>1.3: roll",sum(dl$acwr[ok]>1.3,na.rm=T)," ewma",sum(dl$acwr_ewma[ok]>1.3,na.rm=T)," ; Korrelation:",round(cor(dl$acwr[ok],dl$acwr_ewma[ok],use="c"),2),"\n")
cat("\n--- HIIT-Effekt mit Wochentag-Adjustierung (Messtag), HC-robust\n")
d2 <- dl|>mutate(sleep_ok=!is.na(sleep_h)&sleep_h>=5)
nx <- tibble(date=d2$date-1,ss=ifelse(d2$sleep_ok,d2$sleep_score,NA),hv=ifelse(d2$sleep_ok,d2$hrv_night,NA),bb=ifelse(d2$sleep_ok,d2$bb_high,NA),rh=ifelse(d2$resting_hr>=45,d2$resting_hr,NA))
xx <- d2|>filter(!unrecorded)|>select(date,hiit)|>inner_join(nx,by="date")|>mutate(wd=weekdays(date+1))
print(table(xx$wd,xx$hiit))
for(m in c("ss","hv","bb","rh")){f<-lm(reformulate(c("hiit","wd"),m),data=xx);cs<-summary(f)$coefficients["hiitTRUE",];ci<-confint(f)["hiitTRUE",];cat(m,"adj diff",round(cs[1],2)," CI",round(ci,2)," p",signif(cs[4],2),"\n")}
# Nur Dienstag/Donnerstag als Messtag (nach Mo/Mi-HIIT)
cat("\nNur Messtag Di/Do (n):\n"); y<-xx|>filter(wd%in%c("Tuesday","Thursday"));print(table(y$hiit))
for(m in c("ss","hv","bb","rh")){a1<-na.omit(y[[m]][y$hiit]);b1<-na.omit(y[[m]][!y$hiit]);if(length(a1)>3&&length(b1)>3)cat(m,"diff",round(mean(a1)-mean(b1),2)," p(t)",signif(t.test(a1,b1)$p.value,2),"\n")}
cat("\n--- Gewicht\n"); w<-read_csv(here("data","garmin_weight.csv"),show_col_types=FALSE);cat("sd der Differenzen aufeinanderfolgender:",round(sd(diff(w$weight_kg)),2),"; letzte-erste im 90d-Fenster:\n")
w90<-w|>filter(date>=max(d$date)-89);print(c(first=w90$weight_kg[1],last=tail(w90$weight_kg,1),n=nrow(w90)))
cat("\n--- 7d-Fenster nach Zeilen vs Kalender in daily? Datumslücken:",sum(diff(d$date)!=1),"\n")
cat("\n--- steps heute/gestern\n");print(tail(d|>select(date,steps,kcal_active,sleep_h),3)|>as.data.frame())
cat("Schritte-Ø 90d inkl. heute/gestern vs ohne:",round(mean(tail(d$steps,90),na.rm=T)),round(mean(tail(d$steps,90)[1:88],na.rm=T)),"\n")
